content.arguments:
{"command":"$dir='papers\_tmp'; New-Item -ItemType Directory -Force -Path $dir | Out-Null
foreach($f in 'p1','p2','p3','p4'){
  $t = Get-Content "papers\$f.md" -Raw
  # normalize: break after sentence punctuation / newlines into wrapped lines of ~160 chars
  $wrapped = [regex]::Replace($t, '(.{1,160})', "`$1`r`n")
  Set-Content -Path "$dir\$f.wrapped.md" -Value $wrapped -NoNewline -Encoding utf8
  "{0}: {1} chars -> {2} lines" -f $f, $t.Length, (($wrapped -split "`r`n").Count)
}","description":"Wrap paper text into readable lines"}

